package config

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"os"
	"path/filepath"
	"time"

	"gopkg.in/yaml.v3"
)

// DefaultProxies are the public OpenDHT endpoints shipped in a fresh config,
// matching stunmesh's contrib plugin defaults (both are the Jami proxies).
var DefaultProxies = []string{
	"https://dhtproxy3.jami.net",
	"https://dhtproxy2.jami.net",
}

const DefaultWindow = 50
const DefaultBackend = "opendht"
const DefaultPoll = "60s"

// Config is the persisted node config: identity seed plus connection settings.
// Everything is plain YAML; the only thing secret is Identity (the seed).
type Config struct {
	Identity string   `yaml:"identity"` // 64-hex ed25519 seed, generates a random one if absent
	Name     string   `yaml:"name,omitempty"`
	Backend  string   `yaml:"backend"` // mock | opendht
	Proxies  []string `yaml:"proxies"`
	Window   int      `yaml:"window"`
	Poll     string   `yaml:"poll"` // Go duration, e.g. "60s"
}

// DefaultPath returns the per-user config location (~/.stunmeshchat/config.yaml).
func DefaultPath() string {
	home, err := os.UserHomeDir()
	if err != nil {
		return "config.yaml"
	}
	return filepath.Join(home, ".stunmeshchat", "config.yaml")
}

// Load reads an existing config without modifying the file.
func Load(path string) (*Config, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var c Config
	if err := yaml.Unmarshal(raw, &c); err != nil {
		return nil, fmt.Errorf("parse %s: %w", path, err)
	}
	return &c, nil
}

// LoadOrCreate reads the config, creating it with defaults and a freshly
// generated identity seed if the file (or its identity) is absent. The file is
// written with 0600 perms because it holds the private seed.
func LoadOrCreate(path string) (*Config, error) {
	c, err := Load(path)
	if err == nil {
		// identity present → nothing to do
		if c.Identity != "" {
			fillDefaults(c)
			return c, nil
		}
	} else if !os.IsNotExist(err) {
		return nil, err
	}

	// fresh config (or one missing an identity): give it a new seed + defaults
	if c == nil {
		c = &Config{}
	}
	fillDefaults(c)
	seed, err := newHexSeed()
	if err != nil {
		return nil, err
	}
	c.Identity = seed

	if err := Save(path, c); err != nil {
		return nil, err
	}
	return c, nil
}

func fillDefaults(c *Config) {
	if c.Backend == "" {
		c.Backend = DefaultBackend
	}
	if len(c.Proxies) == 0 {
		c.Proxies = append([]string(nil), DefaultProxies...)
	}
	if c.Window == 0 {
		c.Window = DefaultWindow
	}
	if c.Poll == "" {
		c.Poll = DefaultPoll
	}
}

// Save writes config atomically-ish (temp + rename) with 0600 perms.
func Save(path string, c *Config) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return err
	}
	raw, err := yaml.Marshal(c)
	if err != nil {
		return err
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, raw, 0o600); err != nil {
		return err
	}
	return os.Rename(tmp, path)
}

// PollDuration parses the stored poll interval.
func (c *Config) PollDuration() time.Duration {
	d, err := time.ParseDuration(c.Poll)
	if err != nil || d <= 0 {
		return 60 * time.Second
	}
	return d
}

// SeedBytes decodes Identity from hex.
func (c *Config) SeedBytes() ([]byte, bool) {
	b, err := hex.DecodeString(c.Identity)
	if err != nil || len(b) != 32 {
		return nil, false
	}
	return b, true
}

func newHexSeed() (string, error) {
	b := make([]byte, 32)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

package main

import (
	"context"
	"flag"
	"fmt"
	"net/http"
	"os"
	"os/signal"
	"strings"
	"syscall"
	"time"

	"stunmeshchat/internal/chatd"
	"stunmeshchat/internal/config"
	"stunmeshchat/internal/engine"
)

// chatd runs the serverless group chat as a local HTTP + WebSocket daemon with
// a browser UI. Identity and DHT settings come from the config file; `-yolo`
// keeps everything in memory for quick two-window testing.
func main() {
	var (
		addr    = flag.String("addr", "127.0.0.1:8080", "listen address")
		cfgPath = flag.String("config", config.DefaultPath(), "path to config.yaml")
		room    = flag.String("room", "", "room token (required)")
		name    = flag.String("name", "", "display name (overrides config)")
		seed    = flag.String("seed", "", "64-hex identity seed (overrides config identity)")
		yolo    = flag.Bool("yolo", false, "ephemeral: no config on disk, fresh identity")
		be      = flag.String("backend", "", "storage: mock | opendht (overrides config)")
		prox    = flag.String("proxies", "", "comma-separated OpenDHT endpoints (overrides config)")
		window  = flag.Int("window", 0, "history window N (overrides config)")
		poll    = flag.Duration("poll", 5*time.Second, "poll/refresh interval (default 5s for a live UI)")
	)
	flag.Parse()
	if *room == "" {
		fatalf("usage: chatd -room TOKEN [-name X] [-yolo] [-addr :8080]")
	}

	cfg, ident, displayName := loadConfig(*cfgPath, *room, *name, *seed, *yolo)
	backend := cfg.Backend
	if *be != "" {
		backend = *be
	}
	store := newStore(backend, *prox, cfg)
	if store == nil {
		fatalf("unknown backend %q (mock|opendht)", backend)
	}

	pollInterval := cfg.PollDuration()
	if *poll > 0 {
		pollInterval = *poll
	}
	win := cfg.Window
	if *window > 0 {
		win = *window
	}

	rel := engine.NewReliable(store)
	r := engine.NewRoom(*room, ident, displayName, rel,
		engine.WithWindowSize(win),
		engine.WithPollInterval(pollInterval),
	)
	srv := chatd.NewServer(r, displayName, nil)

	ctx := context.Background()
	r.Run(ctx)
	_ = r.Reconcile(ctx)

	httpSrv := &http.Server{Addr: *addr, Handler: srv.Handler()}
	go func() {
		fmt.Fprintf(os.Stderr, "listening on http://%s  room=%q identity=%s\n",
			*addr, *room, ident.PublicString())
		if err := httpSrv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			fatalf("listen: %v", err)
		}
	}()

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	<-stop
	httpSrv.Shutdown(context.Background())
}

// loadConfig returns a resolved config, identity, and display name. It honors
// the -yolo flag (keep nothing on disk, throwaway identity) like the CLI.
func loadConfig(cfgPath, room, nameFlag, seedFlag string, yolo bool) (*config.Config, *engine.Identity, string) {
	var cfg *config.Config
	var err error
	if yolo {
		cfg = &config.Config{
			Backend: config.DefaultBackend,
			Proxies: append([]string(nil), config.DefaultProxies...),
			Window:  config.DefaultWindow,
			Poll:    config.DefaultPoll,
		}
	} else {
		cfg, err = config.LoadOrCreate(cfgPath)
		if err != nil {
			fatalf("config: %v", err)
		}
		if cfg.Name == "" && nameFlag != "" {
			cfg.Name = nameFlag
			if err := config.Save(cfgPath, cfg); err != nil {
				fmt.Fprintf(os.Stderr, "warn: could not persist name: %v\n", err)
			}
		}
	}

	display := nameFlag
	if display == "" {
		display = cfg.Name
	}
	if display == "" {
		display = "anonymous"
	}

	var ident *engine.Identity
	if seedFlag != "" {
		ident, err = engine.NewIdentityFromHexSeed(seedFlag)
		if err != nil {
			fatalf("seed: %v", err)
		}
	} else if b, ok := cfg.SeedBytes(); ok {
		var s [32]byte
		copy(s[:], b)
		ident = engine.NewIdentityFromSeed(s)
	} else {
		ident, err = engine.NewIdentity()
		if err != nil {
			fatalf("identity: %v", err)
		}
	}
	return cfg, ident, display
}

func newStore(backend, proxyOverride string, cfg *config.Config) engine.Store {
	switch backend {
	case "mock":
		return engine.NewMockStore(10*time.Minute, time.Now)
	case "opendht":
		eps := []string{}
		if proxyOverride != "" {
			for _, e := range strings.Split(proxyOverride, ",") {
				if e = strings.TrimSpace(e); e != "" {
					eps = append(eps, e)
				}
			}
		} else {
			eps = append(eps, cfg.Proxies...)
		}
		return engine.NewOpenDHT(eps)
	default:
		return nil
	}
}

func fatalf(format string, a ...interface{}) {
	fmt.Fprintf(os.Stderr, format+"\n", a...)
	os.Exit(1)
}

