package mesh

import (
	"context"
	"fmt"
	"sort"
	"time"

	"stunmeshchat/internal/engine"
)

// Roster publishes our record and folds everyone's records out of the shared
// DHT key. The key holds a *set* of values (one per publish), so folding
// means: decode, verify, bind-check, freshness-filter, keep highest Seq per
// name.
type Roster struct {
	d       *Deriver
	cidr    *engineSafeIPNet
	me      string
	store   *engine.ReliableStore
	maxAge  time.Duration
	nowFunc func() time.Time
}

type engineSafeIPNet = struct{}

func NewRoster(d *Deriver, me string, store *engine.ReliableStore, cidr *netIPNet) *Roster {
	return &Roster{d: d, me: NormalizeName(me), store: store, maxAge: 24 * time.Hour, nowFunc: time.Now}
}

func (ro *Roster) Publish(ctx context.Context, rec *Record) error {
	b, err := jsonMarshal(rec)
	if err != nil {
		return err
	}
	return ro.store.Publish(ctx, ro.d.RosterKey(), b)
}

// Fetch returns the latest valid record per node, excluding ourselves,
// sorted by name for deterministic iteration.
func (ro *Roster) Fetch(ctx context.Context) (map[string]*Record, error) {
	vals, err := ro.store.Read(ctx, ro.d.RosterKey())
	if err != nil {
		return nil, err
	}
	cidr := ro.cidrNet()
	fresh := ro.nowFunc().Add(-ro.maxAge).Unix()
	out := make(map[string]*Record)
	for _, v := range vals {
		rec, err := DecodeRecord(v)
		if err != nil || rec.TS < fresh {
			continue
		}
		if rec.Name == ro.me {
			continue
		}
		if rec.VerifyBinding(ro.d, cidr) != nil {
			continue
		}
		if cur, ok := out[rec.Name]; ok && cur.Seq >= rec.Seq {
			continue
		}
		out[rec.Name] = rec
	}
	return out, nil
}

func (ro *Roster) Names(peers map[string]*Record) []string {
	names := make([]string, 0, len(peers))
	for n := range peers {
		names = append(names, n)
	}
	sort.Strings(names)
	return names
}

