func srflxOne(ctx context.Context, server string, per time.Duration) (string, error) {
	d := net.Dialer{Timeout: per}
	conn, err := d.DialContext(ctx, "udp", server)
	if err != nil {
		return "", err
	}
	defer conn.Close()

	c, err := stun.NewClient(conn)
	if err != nil {
		return "", err
	}
	defer c.Close()
	c.SetRTO(per)

	type outcome struct {
		addr string
		err  error
	}
	ch := make(chan outcome, 1)
	go func() {
		req := stun.MustBuild(stun.TransactionID, stun.BindingRequest)
		var xor stun.XORMappedAddress
		doErr := c.Do(req, func(e stun.Event) {
			if e.Error != nil {
				ch <- outcome{"", e.Error}
				return
			}
			if perr := e.Message.Parse(&xor); perr != nil {
				ch <- outcome{"", perr}
				return
			}
		})
		if doErr != nil {
			ch <- outcome{"", doErr}
			return
		}
		if xor.IP == nil {
			ch <- outcome{"", errStunFailed}
			return
		}
		ch <- outcome{net.JoinHostPort(xor.IP.String(), strconv.Itoa(xor.Port)), nil}
	}()

	select {
	case <-ctx.Done():
		conn.Close()
		return "", ctx.Err()
	case o := <-ch:
		return o.addr, o.err
	}
}

