package mesh

import (
	"context"
	"fmt"
	"log"
	"net"
	"strconv"
	"time"

	"golang.zx2c4.com/wireguard/wgctrl/wgtypes"

	"stunmeshchat/internal/engine"
)

type Config struct {
	Name        string
	IFace       string
	CIDR        *net.IPNet
	Port        int
	MTU         int
	Poll        time.Duration
	StaleAfter  time.Duration
	StunServers []string
	StunTimeout time.Duration
}

// Daemon ties derivation, roster, candidate gathering, and device control
// into one reconcile loop.
type Daemon struct {
	cfg    Config
	d      *Deriver
	id     *engine.Identity
	key    wgtypes.Key
	myIP   net.IP
	store  *engine.ReliableStore
	dev    Device
	log    *log.Logger
	seq    uint64
	lastGood map[string]Candidate

	gatherLocal func(port int) []Candidate
	gatherSRFLX func(ctx context.Context) []Candidate
	probe       func(peerIP net.IP, port int)
	racePoll    time.Duration
	raceWait    time.Duration
}

func NewDaemon(cfg Config, d *Deriver, store *engine.ReliableStore, dev Device, logger *log.Logger) (*Daemon, error) {
	if cfg.IFace == "" {
		cfg.IFace = "wgmesh0"
	}
	if cfg.Port == 0 {
		cfg.Port = 51820
	}
	if cfg.MTU == 0 {
		cfg.MTU = 1420
	}
	if cfg.Poll <= 0 {
		cfg.Poll = 15 * time.Second
	}
	if cfg.StaleAfter <= 0 {
		cfg.StaleAfter = 180 * time.Second
	}
	if cfg.StunTimeout <= 0 {
		cfg.StunTimeout = 800 * time.Millisecond
	}
	if logger == nil {
		logger = log.Default()
	}
	name := NormalizeName(cfg.Name)
	if err := ValidateName(name); err != nil {
		return nil, err
	}
	cfg.Name = name

	key, err := d.NodeWGKey(name)
	if err != nil {
		return nil, err
	}
	id, err := d.NodeIdentity(name)
	if err != nil {
		return nil, err
	}
	ip, err := d.OverlayIP(name, cfg.CIDR)
	if err != nil {
		return nil, err
	}
	dm := &Daemon{
		cfg: cfg, d: d, id: id, key: key, myIP: ip,
		store: store, dev: dev, log: logger,
		seq:      uint64(time.Now().UnixNano()),
		lastGood: make(map[string]Candidate),
	}
	dm.gatherLocal = func(port int) []Candidate { return LocalCandidates(port) }
	dm.gatherSRFLX = func(ctx context.Context) []Candidate {
		return GatherSRFLX(ctx, cfg.StunServers, cfg.StunTimeout)
	}
	dm.probe = probeUDP
	dm.racePoll = 150 * time.Millisecond
	dm.raceWait = 2500 * time.Millisecond
	return dm, nil
}

func (dm *Daemon) OverlayAddr() *net.IPNet {
	return &net.IPNet{IP: dm.myIP, Mask: net.CIDRMask(32, 32)}
}

// Setup prepares the interface once.
func (dm *Daemon) Setup() error {
	return dm.dev.Setup(dm.key, dm.cfg.Port, dm.cfg.MTU, dm.OverlayAddr(), dm.cfg.CIDR)
}

func (dm *Daemon) nextSeq() uint64 {
	dm.seq++
	return dm.seq
}

// Tick runs one full reconcile pass.
func (dm *Daemon) Tick(ctx context.Context) error {
	mine := append(
		dm.gatherLocal(dm.cfg.Port),
		dm.gatherSRFLX(ctx)...,
	)
	rec := &Record{
		Name:       dm.cfg.Name,
		IP:         dm.myIP.String(),
		Port:       dm.cfg.Port,
		Candidates: mine,
		TS:         time.Now().Unix(),
		Seq:        dm.nextSeq(),
	}
	if err := rec.Sign(dm.id); err != nil {
		return fmt.Errorf("sign record: %w", err)
	}
	if err := dm.store.Publish(ctx, dm.d.RosterKey(), mustMarshal(rec)); err != nil {
		dm.log.Printf("publish failed (continuing): %v", err)
	}

	roster, err := NewRoster(dm.d, dm.cfg.Name, dm.store, dm.cfg.CIDR)
	if err != nil {
		return err
	}
	peers, err := roster.Fetch(ctx)
	if err != nil {
		return fmt.Errorf("fetch roster: %w", err)
	}

	desires := make([]PeerDesire, 0, len(peers))
	for _, name := range Names(peers) {
		desire, raced, err := dm.reconcilePeer(ctx, name, peers[name], mine)
		if err != nil {
			dm.log.Printf("peer %s: %v", name, err)
			continue
		}
		desires = append(desires, desire)
		if raced {
			dm.log.Printf("peer %s: converged via %s %s", name, desire.Endpoint.String(), labelOf(peers[name], lastGoodCandidate(mine, peers[name])))
		}
	}
	return dm.dev.Apply(desires)
}

func lastGoodCandidate(a, b []Candidate) Candidate { return Candidate{} }

func labelOf(rec *Record, _ Candidate) string { return rec.IP }

// reconcilePeer returns the peer's final desired state; races endpoints when
// there is no fresh handshake on a still-announced winner.
func (dm *Daemon) reconcilePeer(ctx context.Context, name string, rec *Record, mine []Candidate) (PeerDesire, bool, error) {
	pubKey, err := dm.d.NodeWGKey(name)
	if err != nil {
		return PeerDesire{}, false, err
	}
	allowed, err := dm.d.OverlayIPNet(name, dm.cfg.CIDR)
	if err != nil {
		return PeerDesire{}, false, err
	}
	desire := PeerDesire{
		Name:      name,
		Pub:       pubKey,
		AllowedIP: *allowed,
		Keepalive: 25 * time.Second,
	}

	winner, haveWinner := dm.lastGood[name]
	fresh := time.Since(dm.dev.Handshake(pubKey)) < dm.cfg.StaleAfter
	stillAnnounced := haveWinner && recHasEndpoint(rec, winner.Addr)

	if fresh && stillAnnounced {
		ep := udpAddrOf(winner)
		desire.Endpoint = ep
		return desire, false, nil
	}

	ordered := OrderEndpoints(mine, rec.Candidates)
	if len(ordered) == 0 {
		return PeerDesire{}, false, fmt.Errorf("no candidates announced")
	}
	for _, cand := range ordered {
		ep, err := net.ResolveUDPAddr("udp", cand.Addr)
		if err != nil {
			continue
		}
		desire.Endpoint = ep
		if dm.tryConnect(pubKey, dm.myIPFor(name), rec.Port) {
			dm.lastGood[name] = cand
			return desire, true, nil
		}
		dm.log.Printf("peer %s: no handshake via %s %s", name, cand.Type, cand.Addr)
	}
	return desire, false, fmt.Errorf("all %d candidates exhausted", len(ordered))
}

func (dm *Daemon) myIPFor(name string) net.IP {
	ip, _ := dm.d.OverlayIP(name, dm.cfg.CIDR)
	return ip
}

func recHasEndpoint(rec *Record, addr string) bool {
	for _, c := range rec.Candidates {
		if c.Addr == addr {
			return true
		}
	}
	return false
}

func udpAddrOf(c Candidate) *net.UDPAddr {
	a, _ := net.ResolveUDPAddr("udp", c.Addr)
	return a
}

// tryConnect pokes the tunnel to trigger a handshake and waits for it.
func (dm *Daemon) tryConnect(pub wgtypes.Key, peerIP net.IP, port int) bool {
	start := time.Now()
	go dm.probe(peerIP, port)
	for deadline := start.Add(dm.raceWait); time.Now().Before(deadline); {
		time.Sleep(dm.racePoll)
		if hs := dm.dev.Handshake(pub); hs.After(start) {
			return true
		}
	}
	return false
}

func probeUDP(peerIP net.IP, port int) {
	conn, err := net.DialTimeout("udp", net.JoinHostPort(peerIP.String(), strconv.Itoa(port)), time.Second)
	if err != nil {
		return
	}
	defer conn.Close()
	_, _ = conn.Write([]byte("routewire-probe"))
}

