	if err := store.Publish(ctx, alpha.d.RosterKey(), marshalRecord2(rec)); err != nil {
		t.Fatal(err)
	}
	if err := alpha.Setup(); err != nil {
		t.Fatal(err)
	}
	dev.Reachable = func(ep *net.UDPAddr) bool { return true }
	if err := alpha.Tick(ctx); err != nil {
		t.Fatal(err)
	}
	firstConvergence := dev.Applies()

	dev.Reachable = func(ep *net.UDPAddr) bool { return false }
	dev.mu.Lock()
	dev.hs = map[[32]byte]time.Time{}
	dev.mu.Unlock()
	if err := alpha.Tick(ctx); err != nil {
		t.Fatal(err)
	}
	if dev.Applies() <= firstConvergence {
		t.Fatal("stale handshake must trigger re-racing attempts")
	}
	if alpha.lastGood["beta"].Addr != "" {
		t.Fatal("failed race must clear lastGood")
	}
}

