**Step 6: Linux device impl** (netlink/wgctrl). File `device_linux.go` with build tag linux:

```go
//go:build linux

package mesh

import (
	"fmt"
	"net"
	"time"

	"github.com/vishvananda/netlink"
	"golang.zx2c4.com/wireguard/wgctrl"
	"golang.zx2c4.com/wireguard/wgctrl/wgtypes"
)

type LinuxDevice struct {
	iface string
	cl    *wgctrl.Client
	link  netlink.Link
}

func NewLinuxDevice(iface string) (*LinuxDevice, error) {
	cl, err := wgctrl.New()
	if err != nil { return nil, err }
	return &LinuxDevice{iface: iface, cl: cl}, nil
}

func (ld *LinuxDevice) Setup(key wgtypes.Key, listenPort, mtu int, addr, route *net.IPNet) error {
	l, err := netlink.LinkByName(ld.iface)
	if err != nil {
		wg := &netlink.Wireguard{LinkAttrs: netlink.LinkAttrs{Name: ld.iface, MTU: mtu}}
		if err := netlink.LinkAdd(wg); err != nil {
			return fmt.Errorf("create %s: %w", ld.iface, err)
		}
		l, err = netlink.LinkByName(ld.iface)
		if err != nil { return err }
	} else if l.Type() != "wireguard" {
		return fmt.Errorf("%s exists but is not a wireguard link", ld.iface)
	}
	ld.link = l
	if mtu > 0 && l.Attrs().MTU != mtu {
		if err := netlink.LinkSetMTU(l, mtu); err != nil { return err }
	}
	priv := key
	port := listenPort
	if err := ld.cl.ConfigureDevice(ld.iface, wgtypes.Config{PrivateKey: &priv, ListenPort: &port}); err != nil {
		return err
	}
	a := &netlink.Addr{IPNet: &net.IPNet{IP: addr.IP, Mask: net.CIDRMask(32, 32)}}
	if err := netlink.AddrReplace(l, a); err != nil { return err }
	if route != nil {
		if err := netlink.RouteReplace(&netlink.Route{LinkIndex: l.Attrs().Index, Dst: route}); err != nil {
			return err
		}
	}
	return netlink.LinkSetUp(l)
}

func (ld *LinuxDevice) Apply(peers []PeerDesire) error {
	cfg := wgtypes.Config{ReplacePeers: true}
	for _, p := range peers {
		pc := wgtypes.PeerConfig{
			PublicKey: p.Pub,
			AllowedIPs: []net.IPNet{p.AllowedIP},
			PersistentKeepaliveInterval: &p.Keepalive,
		}
		if p.Endpoint != nil { pc.Endpoint = p.Endpoint }
		cfg.Peers = append(cfg.Peers, pc)
	}
	return ld.cl.ConfigureDevice(ld.iface, cfg)
}

func (ld *LinuxDevice) Handshake(pub wgtypes.Key) time.Time {
	dev, err := ld.cl.Device(ld.iface)
	if err != nil { return time.Time{} }
	for _, p := range dev.Peers {
		if p.PublicKey == pub { return p.LastHandshake }
	}
	return time.Time{}
}

func (ld *LinuxDevice) Close() error { return ld.cl.Close() }
```

