package main

import (
	"context"
	"errors"
	"flag"
	"fmt"
	"log"
	"net"
	"os"
	"os/signal"
	"strconv"
	"strings"
	"syscall"
	"time"

	"stunmeshchat/internal/config"
	"stunmeshchat/internal/engine"
	"stunmeshchat/internal/mesh"
)

var defaultStunServers = []string{
	"stun.l.google.com:19402",
	"stun1.l.google.com:19402",
	"stun.cloudflare.com:3478",
}

func main() {
	log.SetFlags(log.LstdFlags | log.Lmicroseconds)

	var (
		pskFlag = flag.String("psk", os.Getenv("MESH_PSK"), "mesh PSK (required; env MESH_PSK)")
		nameF   = flag.String("name", defaultName(), "node name [a-z0-9-] (default hostname)")
		ifaceF  = flag.String("iface", "wgmesh0", "wireguard interface")
		cidrF   = flag.String("cidr", "10.99.0.0/16", "overlay CIDR")
		portF   = flag.Int("port", 51820, "WireGuard listen port")
		mtuF    = flag.Int("mtu", 1420, "interface MTU")
		pollF   = flag.Duration("poll", 15*time.Second, "reconcile interval")
		staleF  = flag.Duration("stale", 180*time.Second, "handshake staleness before re-race")
		stunF   = flag.String("stun", strings.Join(defaultStunServers, ","), "STUN servers (comma-separated, empty disables)")
		proxF   = flag.String("proxies", "", "OpenDHT proxies (comma-separated; default: config defaults)")
		beF     = flag.String("backend", "opendht", "roster backend: opendht | mock")
		dryF    = flag.Bool("dry-run", false, "no kernel changes; simulate device control")
		stopF   = flag.Bool("stop", false, "delete interface and exit")
	)
	flag.Parse()

	if strings.TrimSpace(*pskFlag) == "" {
		fatalf("missing PSK: pass -psk or set MESH_PSK")
	}

	cidrIP, cidrNet, err := net.ParseCIDR(*cidrF)
	if err != nil {
		fatalf("bad -cidr: %v", err)
	}
	_ = cidrIP

	stunServers := []string{}
	for _, s := range strings.Split(*stunF, ",") {
		if s = strings.TrimSpace(s); s != "" {
			stunServers = append(stunServers, s)
		}
	}

	deriver := mesh.NewDeriver(*pskFlag)

	store := newStore(*beF, *proxF)
	logger := log.Default()

	var dev mesh.Device
	var stopper func()
	if *dryF {
		fd := mesh.NewFakeDevice()
		dev = fd
		stopper = func() {}
		logger.Printf("mode=dry-run device=fake")
	} else {
		ld, err := mesh.NewLinuxDevice(*ifaceF)
		if err != nil {
			fatalf("device: %v", err)
		}
		dev = ld
		stopper = func() { _ = ld.Close() }
	}

	daemon, err := mesh.NewDaemon(mesh.Config{
		Name:        *nameF,
		IFace:       *ifaceF,
		CIDR:        cidrNet,
		Port:        *portF,
		MTU:         *mtuF,
		Poll:        *pollF,
		StaleAfter:  *staleF,
		StunServers: stunServers,
	}, deriver, store, dev, logger)
	if err != nil {
		fatalf("daemon: %v", err)
	}

	if *stopF {
		if err := stopInterface(*ifaceF); err != nil {
			fatalf("stop: %v", err)
		}
		fmt.Println("stopped")
		return
	}

	pubKey, err := deriver.NodeWGKey(daemon.Name())
	if err != nil {
		fatalf("key: %v", err)
	}

	ctx, cancel := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer cancel()

	logger.Printf("routewire/meshd starting node=%s overlay=%s listen=%d iface=%s backend=%s roster=%s",
		daemon.Name(), daemon.OverlayAddr().IP, *portF, *ifaceF, *beF, deriver.RosterKey())
	logger.Printf("public-key=%s", pubKey)

	if err := daemon.Setup(); err != nil {
		fatalf("setup: %v", err)
	}

	done := make(chan struct{})
	go func() {
		defer close(done)
		daemon.Run(ctx)
	}()

	firstTickCtx, cancelFirst := context.WithTimeout(context.Background(), 30*time.Second)
	if err := daemon.Tick(firstTickCtx); err != nil {
		logger.Printf("first tick: %v", err)
	}
	cancelFirst()

	<-done
	stopper()
	logger.Printf("bye")
}

func newStore(backend, proxyOverride string) *engine.ReliableStore {
	switch backend {
	case "mock":
		return engine.NewReliable(engine.NewMockStore(10*time.Minute, time.Now))
	case "opendht":
		endpoints := config.DefaultProxies
		if proxyOverride != "" {
			endpoints = nil
			for _, e := range strings.Split(proxyOverride, ",") {
				if e = strings.TrimSpace(e); e != "" {
					endpoints = append(endpoints, e)
				}
			}
		}
		return engine.NewReliable(engine.NewOpenDHT(endpoints))
	default:
		fatalf("unknown backend %q (opendht|mock)", backend)
		return nil
	}
}

func stopInterface(iface string) error {
	if iface == "" {
		return errors.New("no iface")
	}
	ld, err := mesh.NewLinuxDevice(iface)
	if err != nil {
		return err
	}
	defer ld.Close()
	return ld.Delete()
}

func defaultName() string {
	h, err := os.Hostname()
	if err != nil {
		return "node-" + strconv.Itoa(os.Getpid())
	}
	n := strings.ToLower(h)
	n = strings.Map(func(r rune) rune {
		switch {
		case r >= 'a' && r <= 'z', r >= '0' && r <= '9', r == '-':
			return r
		default:
			return -1
		}
	}, n)
	if n == "" {
		n = "node"
	}
	return n
}

func fatalf(format string, a ...any) {
	fmt.Fprintf(os.Stderr, format+"\n", a...)
	os.Exit(1)
}

