	_ = cidrIP
	dm, err := NewDaemon(Config{
		Name: name,
		CIDR: cidrNet,
	}, d, store, dev, nil)
	if err != nil {
		t.Fatal(err)
	}
	dm.gatherLocal = func(int) []Candidate { return []Candidate{{Type: CandHost, Addr: hostPort}} }
	dm.racePoll = 5 * time.Millisecond
	dm.raceWait = 50 * time.Millisecond
	return dm, d
}

