func parseCIDRs(ss []string) []net.IPNet {
	var out []net.IPNet
	seen := map[string]bool{}
	for _, s := range ss {
		_, ipnet, err := net.ParseCIDR(strings.TrimSpace(s))
		if err != nil || seen[ipnet.String()] {
			continue
		}
		seen[ipnet.String()] = true
		out = append(out, *ipnet)
	}
	return out
}

