package mesh

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net"
	"strings"
	"time"

	"stunmeshchat/internal/engine"
)

// ExportConfInput describes one generated remote-device config.
type ExportConfInput struct {
	Deriver     *Deriver
	CIDR        *net.IPNet
	LocalName   string   // generating node; becomes the [Peer] hub
	RemoteName  string   // agent-less device receiving this config
	Endpoint    string   // host:port where the remote can reach the local node
	ExtraRoutes []string // announced subnets to bake into AllowedIPs
	MTU         int
}

// ExportConf renders a wg-quick(8)-compatible config for a device that cannot
// run meshd. The remote's private key is derived from PSK+name exactly like an
// agent's, so agents that later see its roster record interoperate with zero
// extra state.
func ExportConf(in ExportConfInput) ([]byte, error) {
	if in.Deriver == nil || in.CIDR == nil {
		return nil, errors.New("export: deriver and cidr required")
	}
	local := NormalizeName(in.LocalName)
	remote := NormalizeName(in.RemoteName)
	if err := ValidateName(remote); err != nil {
		return nil, fmt.Errorf("export: remote name: %w", err)
	}
	if remote == local {
		return nil, errors.New("export: remote name must differ from this node's name")
	}
	if _, _, err := net.SplitHostPort(in.Endpoint); err != nil {
		return nil, fmt.Errorf("export: endpoint must be host:port: %w", err)
	}
	mtu := in.MTU
	if mtu <= 0 {
		mtu = 1420
	}

	priv, err := in.Deriver.NodeWGKey(remote)
	if err != nil {
		return nil, err
	}
	ip, err := in.Deriver.OverlayIP(remote, in.CIDR)
	if err != nil {
		return nil, err
	}
	hubPub, err := in.Deriver.NodeWGKey(local)
	if err != nil {
		return nil, err
	}

	routes := parseCIDRs(in.ExtraRoutes)
	allowed := make([]string, 0, len(routes)+1)
	allowed = append(allowed, in.CIDR.String())
	for i := range routes {
		allowed = append(allowed, routes[i].String())
	}

	var b strings.Builder
	fmt.Fprintf(&b, "# routewire/meshd exported config for %q\n", remote)
	fmt.Fprintf(&b, "# generated %s by node %q from its live routing knowledge.\n",
		time.Now().UTC().Format(time.RFC3339), local)
	fmt.Fprintf(&b, "# regenerate to refresh endpoints/routes; keep this file secret (0600).\n")
	b.WriteString("\n[Interface]\n")
	fmt.Fprintf(&b, "PrivateKey = %s\n", priv.String())
	fmt.Fprintf(&b, "Address = %s/32\n", ip)
	fmt.Fprintf(&b, "MTU = %d\n", mtu)
	b.WriteString("\n[Peer]\n")
	fmt.Fprintf(&b, "# routewire hub %q (regenerate there after topology changes)\n", local)
	fmt.Fprintf(&b, "PublicKey = %s\n", hubPub.PublicKey().String())
	fmt.Fprintf(&b, "Endpoint = %s\n", in.Endpoint)
	fmt.Fprintf(&b, "AllowedIPs = %s\n", strings.Join(allowed, ", "))
	b.WriteString("PersistentKeepalive = 25\n")

	return []byte(b.String()), nil
}

// PublishRemoteRecord publishes the remote device's roster record on its
// behalf so every agent auto-adds it during their next tick. The remote has
// no listener, so the record carries no candidates; agents learn the return
// path when the device's first keepalive arrives (WireGuard roaming).
func PublishRemoteRecord(ctx context.Context, store *engine.ReliableStore, d *Deriver, cidr *net.IPNet, remoteName string) error {
	remote := NormalizeName(remoteName)
	if err := ValidateName(remote); err != nil {
		return fmt.Errorf("publish remote: %w", err)
	}
	ip, err := d.OverlayIP(remote, cidr)
	if err != nil {
		return err
	}
	id, err := d.NodeIdentity(remote)
	if err != nil {
		return err
	}
	rec := &Record{
		Name: remote,
		IP:   ip.String(),
		Port: 0,
		TS:   time.Now().Unix(),
		Seq:  1,
	}
	if err := rec.Sign(id); err != nil {
		return err
	}
	if err := rec.VerifyBinding(d, cidr); err != nil {
		return err
	}
	raw, err := json.Marshal(rec)
	if err != nil {
		return err
	}
	if _, err := DecodeRecord(raw); err != nil {
		return fmt.Errorf("publish remote: self-check failed: %w", err)
	}
	return store.Publish(ctx, d.RosterKey(), raw)
}

package mesh

import (
	"context"
	"net"
	"strings"
	"testing"
	"time"

	"stunmeshchat/internal/engine"
)

func parseINI(t *testing.T, conf []byte) map[string]map[string]string {
	t.Helper()
	out := map[string]map[string]string{"": {}}
	cur := ""
	for _, line := range strings.Split(string(conf), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if strings.HasPrefix(line, "[") {
			cur = strings.Trim(line, "[]")
			out[cur] = map[string]string{}
			continue
		}
		k, v, ok := strings.Cut(line, "=")
		if !ok {
			t.Fatalf("bad ini line %q", line)
		}
		out[cur][strings.TrimSpace(k)] = strings.TrimSpace(v)
	}
	return out
}

func TestExportConfGolden(t *testing.T) {
	d := NewDeriver("test-psk")
	cidr := mustCIDR(t, "10.99.0.0/16")

	conf, err := ExportConf(ExportConfInput{
		Deriver:     d,
		CIDR:        cidr,
		LocalName:   "alpha",
		RemoteName:  "phone-1",
		Endpoint:    "192.168.1.10:51820",
		ExtraRoutes: []string{"192.168.50.0/24", "bogus"},
		MTU:         1420,
	})
	if err != nil {
		t.Fatal(err)
	}

	ini := parseINI(t, conf)
	ifc := ini["Interface"]
	peer := ini["Peer"]
	if ifc == nil || peer == nil {
		t.Fatalf("missing sections: %v", ini)
	}

	wantPriv, err := d.NodeWGKey("phone-1")
	if err != nil {
		t.Fatal(err)
	}
	if ifc["PrivateKey"] != wantPriv.String() {
		t.Fatalf("private key must be derived phone-1 key:\n got %s\nwant %s", ifc["PrivateKey"], wantPriv.String())
	}
	wantIP, _ := d.OverlayIP("phone-1", cidr)
	if ifc["Address"] != wantIP.String()+"/32" {
		t.Fatalf("address: got %q want %q", ifc["Address"], wantIP.String()+"/32")
	}
	if ifc["MTU"] != "1420" {
		t.Fatalf("mtu: %q", ifc["MTU"])
	}

	hubPub, _ := d.NodeWGKey("alpha")
	if peer["PublicKey"] != hubPub.PublicKey().String() {
		t.Fatalf("peer pubkey must be alpha's: %q", peer["PublicKey"])
	}
	if peer["Endpoint"] != "192.168.1.10:51820" {
		t.Fatalf("endpoint: %q", peer["Endpoint"])
	}
	gotAllowed := strings.Split(peer["AllowedIPs"], ", ")
	want := map[string]bool{"10.99.0.0/16": true, "192.168.50.0/24": true}
	if len(gotAllowed) != len(want) {
		t.Fatalf("allowedips must contain exactly cidr+valid routes: %v", gotAllowed)
	}
	for _, a := range gotAllowed {
		if !want[a] {
			t.Fatalf("unexpected allowedip %q (bogus leaked?)", a)
		}
	}
	if peer["PersistentKeepalive"] != "25" {
		t.Fatalf("keepalive: %q", peer["PersistentKeepalive"])
	}
}

func TestExportConfRejects(t *testing.T) {
	d := NewDeriver("k")
	cidr := mustCIDR(t, "10.99.0.0/16")

	if _, err := ExportConf(ExportConfInput{Deriver: d, CIDR: cidr, LocalName: "a", RemoteName: "a", Endpoint: "1.2.3.4:5"}); err == nil {
		t.Fatal("remote==local must fail")
	}
