package main

import (
	"context"
	"errors"
	"flag"
	"fmt"
	"log"
	"net"
	"os"
	"os/signal"
	"strconv"
	"strings"
	"syscall"
	"time"

	"stunmeshchat/internal/config"
	"stunmeshchat/internal/engine"
	"stunmeshchat/internal/mesh"
)

var defaultStunServers = []string{
	"stun.l.google.com:19402",
	"stun1.l.google.com:19402",
	"stun.cloudflare.com:3478",
}

func main() {
	log.SetFlags(log.LstdFlags | log.Lmicroseconds)

	var (
		configF = flag.String("config", "", "config file path (.yaml or .json)")

		pskF   = flag.String("psk", "", "mesh PSK (or MESH_PSK / config psk)")
		nameF  = flag.String("name", "", "node name [a-z0-9-] (default hostname)")
		ifaceF = flag.String("iface", "", "wireguard interface (default wgmesh0)")
		cidrF  = flag.String("cidr", "", "overlay CIDR (default 10.99.0.0/16)")
		portF  = flag.Int("port", 0, "WireGuard listen port (default 51820)")
		mtuF   = flag.Int("mtu", 0, "interface MTU (default 1420)")
		pollF  = flag.Duration("poll", 0, "reconcile interval (default 15s)")
		staleF = flag.Duration("stale", 0, "handshake staleness before re-race (default 180s)")
		stunF  = flag.String("stun", "", "STUN servers, comma-separated (empty disables)")
		proxF  = flag.String("proxies", "", "OpenDHT proxies, comma-separated")
		beF    = flag.String("backend", "", "roster backend: opendht | mock (default opendht)")
		annF   = flag.String("announce", "", "subnets this node serves, comma-separated CIDRs")

		dryF  = flag.Bool("dry-run", false, "no kernel changes; simulate device control")
		stopF = flag.Bool("stop", false, "delete interface and exit")

		exportF  = flag.Bool("export", false, "generate a wg-quick config for -remote and exit")
		remoteF  = flag.String("remote", "", "remote device name for -export")
		outF     = flag.String("out", "", "write exported config to file (0600) instead of stdout")
		epF      = flag.String("endpoint", "", "endpoint for exported peer (default: this node's best local address:port)")
		routesF  = flag.String("routes", "", `with -export: "all" bakes every announced subnet known at generation into AllowedIPs`)
	)
	flag.Parse()

	setFlags := map[string]string{}
	flag.Visit(func(f *flag.Flag) { setFlags[f.Name] = f.Value.String() })

	env := map[string]string{}
	if v := os.Getenv("MESH_PSK"); v != "" {
		env["MESH_PSK"] = v
	}
	if v := os.Getenv("MESH_NAME"); v != "" {
		env["MESH_NAME"] = v
	}

	var fileCfg *config.MeshConfig
	if *configF != "" {
		var err error
		fileCfg, err = config.LoadMeshConfig(*configF)
		if err != nil {
			fatalf("config: %v", err)
		}
	}

	defs := &config.MeshConfig{
		Name:     defaultName(),
		IFace:    "wgmesh0",
		CIDR:     "10.99.0.0/16",
		Port:     51820,
		MTU:      1420,
		Poll:     "15s",
		Stale:    "3m",
		Backend:  "opendht",
	}
	resolved := config.ResolveMesh(defs, fileCfg, env, setFlags)

	logger := log.Default()
	cidrIP, cidrNet, err := net.ParseCIDR(resolved.CIDR)
	if err != nil || cidrIP == nil {
		fatalf("bad cidr %q: %v", resolved.CIDR, err)
	}
	poll, err := time.ParseDuration(resolved.Poll)
	if err != nil {
		fatalf("bad poll %q: %v", resolved.Poll, err)
	}
	staleAfter, err := time.ParseDuration(resolved.Stale)
	if err != nil {
		fatalf("bad stale %q: %v", resolved.Stale, err)
	}
	for _, a := range resolved.Announce {
		if _, _, err := net.ParseCIDR(strings.TrimSpace(a)); err != nil {
			fatalf("bad announce entry %q: %v", a, err)
		}
	}

	deriver := mesh.NewDeriver(resolved.PSK)
	store := newStore(resolved.Backend, strings.Join(resolved.Proxies, ","))

	if *exportF {
		runExport(deriver, store, cidrNet, resolved, *remoteF, *outF, *epF, *routesF, logger)
		return
	}

	if strings.TrimSpace(resolved.PSK) == "" {
		fatalf("missing PSK: use -psk, MESH_PSK, or config file")
	}

	var dev mesh.Device
	var stopper func()
	if resolved.DryRun {
		dev = mesh.NewFakeDevice()
		stopper = func() {}
		logger.Printf("mode=dry-run device=fake")
	} else {
		ld, err := mesh.NewLinuxDevice(resolved.IFace)
		if err != nil {
			fatalf("device: %v", err)
		}
		dev = ld
		stopper = func() { _ = ld.Close() }
	}

	daemon, err := mesh.NewDaemon(mesh.Config{
		Name:        resolved.Name,
		IFace:       resolved.IFace,
		CIDR:        cidrNet,
		Port:        resolved.Port,
		MTU:         resolved.MTU,
		Poll:        poll,
		StaleAfter:  staleAfter,
		StunServers: resolved.Stun,
		Announce:    resolved.Announce,
	}, deriver, store, dev, logger)
	if err != nil {
		fatalf("daemon: %v", err)
	}

	if *stopF {
		if err := stopInterface(resolved.IFace); err != nil {
			fatalf("stop: %v", err)
		}
		fmt.Println("stopped")
		return
	}

	pubKey, err := deriver.NodeWGKey(daemon.Name())
	if err != nil {
		fatalf("key: %v", err)
	}

	ctx, cancel := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer cancel()

	logger.Printf("routewire/meshd starting node=%s overlay=%s listen=%d iface=%s backend=%s announce=%v roster=%s",
		daemon.Name(), daemon.OverlayAddr().IP, resolved.Port, resolved.IFace, resolved.Backend,
		resolved.Announce, deriver.RosterKey())
	logger.Printf("public-key=%s", pubKey)

	if err := daemon.Setup(); err != nil {
		fatalf("setup: %v", err)
	}

	done := make(chan struct{})
	go func() {
		defer close(done)
		daemon.Run(ctx)
	}()

	firstTickCtx, cancelFirst := context.WithTimeout(context.Background(), 30*time.Second)
	if err := daemon.Tick(firstTickCtx); err != nil {
		logger.Printf("first tick: %v", err)
	}
	cancelFirst()

	<-done
	stopper()
	logger.Printf("bye")
}

func runExport(deriver *mesh.Deriver, store *engine.ReliableStore, cidr *net.IPNet, rc *config.MeshConfig, remoteRaw, outPath, endpointFlag, routesFlag string, logger *log.Logger) {
	if strings.TrimSpace(rc.PSK) == "" {
		fatalf("missing PSK: use -psk, MESH_PSK, or config file")
	}
	if remoteRaw == "" {
		fatalf("-export requires -remote NAME")
	}
	switch routesFlag {
	case "", "all":
	default:
		fatalf("-routes must be empty or \"all\"")
	}

	endpoint := endpointFlag
	if endpoint == "" {
		cands := mesh.LocalCandidates(rc.Port)
		for _, c := range cands {
			if c.Type == mesh.CandHost {
				endpoint = c.Addr
				break
			}
		}
		if endpoint == "" {
			for _, c := range cands {
				if c.Type == mesh.CandSRFLX {
					endpoint = c.Addr
					break
				}
			}
		}
		if endpoint == "" {
			fatalf("no usable local address found; pass -endpoint host:port explicitly")
		}
		logger.Printf("endpoint auto-detected: %s (override with -endpoint)", endpoint)
	}

	extra := []string(nil)
	if routesFlag == "all" {
		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		defer cancel()
		ro, err := mesh.NewRoster(deriver, rc.Name, store, cidr)
		if err != nil {
			fatalf("roster: %v", err)
		}
		recs, err := ro.Fetch(ctx)
		if err != nil {
			logger.Printf("warning: could not fetch roster (%v); exporting overlay-only routes", err)
		}
		for _, rec := range recs {
			extra = append(extra, rec.Adv...)
		}
	}

	conf, err := mesh.ExportConf(mesh.ExportConfInput{
		Deriver:     deriver,
		CIDR:        cidr,
		LocalName:   rc.Name,
		RemoteName:  remoteRaw,
		Endpoint:    endpoint,
		ExtraRoutes: extra,
		MTU:         rc.MTU,
	})
	if err != nil {
		fatalf("export: %v", err)
	}

	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	if err := mesh.PublishRemoteRecord(ctx, store, deriver, cidr, remoteRaw); err != nil {
		logger.Printf("WARNING: could not publish roster record for %q (%v); agents will not auto-configure its peer until it succeeds",
			mesh.NormalizeName(remoteRaw), err)
	} else {
		logger.Printf("published roster record for %q; agents will add it on next tick", mesh.NormalizeName(remoteRaw))
	}

	if outPath == "" {
		os.Stdout.Write(conf)
		return
	}
	if err := os.WriteFile(outPath, conf, 0o600); err != nil {
		fatalf("write %s: %v", outPath, err)
	}
	fmt.Fprintf(os.Stderr, "wrote %s (mode 0600)\n", outPath)
}

func newStore(backend, proxyOverride string) *engine.ReliableStore {
	switch backend {
	case "mock":
		return engine.NewReliable(engine.NewMockStore(10*time.Minute, time.Now))
	case "opendht":
		endpoints := config.DefaultProxies
		if proxyOverride != "" {
			endpoints = nil
			for _, e := range strings.Split(proxyOverride, ",") {
				if e = strings.TrimSpace(e); e != "" {
					endpoints = append(endpoints, e)
				}
			}
		}
		return engine.NewReliable(engine.NewOpenDHT(endpoints))
	default:
		fatalf("unknown backend %q (opendht|mock)", backend)
		return nil
	}
}

func stopInterface(iface string) error {
	if iface == "" {
		return errors.New("no iface")
	}
	ld, err := mesh.NewLinuxDevice(iface)
	if err != nil {
		return err
	}
	defer ld.Close()
	return ld.Delete()
}

func defaultName() string {
	h, err := os.Hostname()
	if err != nil {
		return "node-" + strconv.Itoa(os.Getpid())
	}
	n := strings.ToLower(h)
	n = strings.Map(func(r rune) rune {
		switch {
		case r >= 'a' && r <= 'z', r >= '0' && r <= '9', r == '-':
			return r
		default:
			return -1
		}
	}, n)
	if n == "" {
		n = "node"
	}
	return n
}

func fatalf(format string, a ...any) {
	fmt.Fprintf(os.Stderr, format+"\n", a...)
	os.Exit(1)
}

