func main() {
	log.SetFlags(log.LstdFlags | log.Lmicroseconds)

	// dsnet-style subcommands: "meshd init", "meshd export", "meshd stop"
	// are sugar for their flag equivalents.
	os.Args = append(os.Args[:1], expandSubcommand(os.Args[1:])...)

// expandSubcommand maps a leading subcommand to its flag equivalent so
// "meshd init -name x" parses identically to "meshd -init -name x".
func expandSubcommand(args []string) []string {
	if len(args) == 0 {
		return args
	}
	var flagName string
	switch args[0] {
	case "init":
		flagName = "-init"
	case "export":
		flagName = "-export"
	case "stop":
		flagName = "-stop"
	default:
		return args
	}
	return append([]string{flagName}, args[1:]...)
}

